import java.util.HashMap;
import java.util.Map;

public class ConfigurationManager {
    private final Map<String, String> properties = new HashMap<>();

    public void setProperty(String key, String value) {
        if (key == null) throw new IllegalArgumentException("Property key cannot be null");
        properties.put(key.trim().toLowerCase(), value);
    }

    public String getProperty(String key, String fallback) {
        if (key == null) return fallback;
        return properties.getOrDefault(key.trim().toLowerCase(), fallback);
    }

    public boolean hasProperty(String key) {
        if (key == null) return false;
        return properties.containsKey(key.trim().toLowerCase());
    }

    public static void main(String[] args) {
        ConfigurationManager config = new ConfigurationManager();
        config.setProperty("server.port", "8080");
        config.setProperty("database.pool.size", "20");

        System.out.println("Port: " + config.getProperty("SERVER.PORT", "3000"));
        System.out.println("Timeout: " + config.getProperty("server.timeout", "5000"));
        System.out.println("Has pool config? " + config.hasProperty("database.pool.size"));
    }
}

